def main(argv):
    target = argv[1] if len(argv) > 1 else DEFAULT_TARGET
    print("Hybrid Studio bootstrap -> %s" % target)
    total_lines = 0
    for rel in sorted(FILES):
        content = FILES[rel]
        dest = os.path.join(target, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "w", encoding="utf-8") as fh:
            fh.write(content)
        lines = content.count("\n") + (0 if content.endswith("\n") or not content else 1)
        total_lines += lines
        print("  wrote %-45s %5d lines" % (rel, lines))
    print("Done: %d files, %d total lines." % (len(FILES), total_lines))
    print("Next: run tests with:  python3 %s" % os.path.join(target, "tests", "run_pure_tests.py"))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
